for _n in (1, 2, 3, 5, 7):
    for _shift in (-3.0, 0.0, 4.0):
        _lg = [i * 0.5 + _shift for i in range(_n)]
        for _t in (0.5, 1.0, 3.0):
            _p = softmax(_lg, _t)
            assert abs(sum(_p) - 1.0) < 1e-9, (_n, _shift, _t, _p)
            _ref = softmax([z / _t for z in _lg], 1.0)
            for _i in range(_n):
